!! Boys function tabulated grid data for integral evaluation
module boys
  !! Provides pre-tabulated Boys function values for efficient evaluation.
  !!
  !! The Boys function F_m(t) is defined as:
  !!
  !! $$ F_m(t) = \int_0^1 u^{2m} e^{-tu^2} du $$
  !!
  !! It appears in the evaluation of two-electron integrals over Gaussian
  !! basis functions. This module provides a tabulated grid (~18,000 points)
  !! for interpolation-based evaluation, which is faster than direct
  !! numerical integration for the range of t values encountered.
  !!
  !! For large t (> t_max), asymptotic expansions are used instead.
  use liberi_types, only: dp

  private

  public :: f_increment, boys_grid_zero, exponent_grid
  public :: t_max, m_increment

  real(dp), parameter :: t_max = 2.5000000000000000e+01_dp
    !! Maximum t value for tabulated grid; use asymptotic form for t > t_max
  real(dp), parameter :: m_increment = 2.7689158581207256e+01_dp
    !! Grid spacing increment parameter

